    for (i in 1:n) {

        col(loglam,i) ~ multi_normal(col(mu,i),Sigma);
        Y1[i] ~ poisson_log(col(loglam,i)[1]);
        Y2[i] ~ poisson_log(col(loglam,i)[2]);
    }
    tau ~ uniform(-1, 1);
}
'
dat <- list(n = n, mu=rbind(mu1,mu2), Y1=Y1, Y2=Y2,#Y=cbind(Y1,Y2),
    sigma1=sigma1, sigma2=sigma2)

f <- stan(model_code=joint_PLn, data=dat)

